use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:2.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_parkinson_volatility",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,last:Option<f64>,v:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{Ok(Box::new(I{p:x[0]as usize,last:None,v:RingVec::new(x[0]as usize)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{if let Some(p)=self.last{self.v.push((t.price/p).ln().powi(2)/(4.*2f64.ln()));};self.last=Some(t.price);(self.v.len()==self.p).then(||(self.v.iter().sum::<f64>()/self.p as f64).sqrt())}}
